'use strict';
// Owner-only synthetic inbound observations. No signing, RPC or manual balance adjustment.
const depositLabels={waiting:['Ожидаем перевод','Waiting for transfer'],pending:['Перевод найден · ждём подтверждения','Transfer found · awaiting confirmation'],unknown:['Нужна проверка · результат неизвестен','Needs review · outcome unknown'],confirmed:['Зачислено','Credited'],mismatch:['Реквизиты не совпадают · не зачислено','Details do not match · not credited'],failed:['Перевод не состоялся','Transfer failed']};
function depositState(){return finance.deposit??={source:ownRoutes[0].id,records:[],outcome:'pending',notice:null};}
const depositAllowed=()=>ownWrite();
const depositRoute=id=>ownRoutes.find(r=>r.id===id);
const depositCredited=id=>(finance.deposit?.records||[]).filter(x=>x.source===id&&x.status==='confirmed').reduce((n,x)=>n+x.units,0);
const depositCurrent=()=>depositState().records.find(x=>x.source===depositState().source);
function depositEvent(source){const r=depositRoute(source);return {network:r.network,asset:r.asset,contract:'DEMO-CONTRACT-'+r.asset,recipient:r.address,tx:'TX-DEMO-IN-'+source,event:0,units:250000000};}
const depositKey=e=>JSON.stringify([e.network,e.tx,e.event,e.contract,e.recipient]);
function depositObserve(e,status){if(!depositAllowed()||!['pending','unknown','confirmed','failed'].includes(status))return false;const x=depositState(),r=depositRoute(x.source);if(!r)return false;const expected=depositEvent(r.id);const match=e.network===r.network&&e.asset===r.asset&&e.contract===expected.contract&&e.recipient===r.address&&Number.isSafeInteger(e.units)&&e.units>0&&typeof e.tx==='string'&&e.tx.length>0&&Number.isSafeInteger(e.event)&&e.event>=0;
 if(!match){x.notice=['Не совпали сеть, актив или получатель. Сумма не зачислена; проверьте исходный перевод.','Network, asset or recipient mismatch. Nothing credited; check the original transfer.'];return false;}
 let p=x.records.find(p=>p.key===depositKey(e));if(p){if(p.units!==e.units||p.source!==r.id){x.notice=['Подтверждающие данные противоречат прежним. Баланс не изменён.','Evidence conflicts with the previous observation. Balance unchanged.'];return false;}if(['confirmed','failed'].includes(p.status)){x.notice=['Исходная операция уже учтена. Повторного зачисления нет.','Original transfer already recorded. No duplicate credit.'];return true;}}
 else{p={...e,id:'IN-DEMO-'+(x.records.length+1),key:depositKey(e),source:r.id,status:'waiting'};x.records.push(p);}
 if(p.status!==status){p.status=status;p.checkedAt=new Date().toISOString();flog('Проверено внешнее пополнение '+p.id+': '+status,'External funding checked '+p.id+': '+status);}
 x.notice=status==='confirmed'?['Поступление подтверждено и учтено один раз как финансирование.','Receipt confirmed and recorded once as funding.']:['Перевод проверен. Неподтверждённая сумма не входит в доступные средства.','Transfer checked. Unconfirmed funds are not available.'];return true;
}
function depositAction(a){if(!depositAllowed())return false;const x=depositState();x.notice=null;
 if(a==='open'){if(finance.view==='own')x.source=ownState().source;finance.view='deposit';navigate('finance');return true;}
 if(a==='withdraw'){ownState().source=x.source;finance.view='own';navigate('finance');return true;}
 if(a==='check'){const e=depositEvent(x.source);if(x.outcome==='mismatch')e.network='UNSUPPORTED-DEMO-NETWORK';return depositObserve(e,x.outcome==='mismatch'?'pending':x.outcome);}
 return false;
}
function depositHistory(){const x=depositState();return `<section class="panel"><h2>${pl('История пополнений','Funding history')}</h2>${x.records.length?financeTable([pl('Операция / сеть','Transfer / network'),pl('Получено','Received'),pl('Состояние','Status'),pl('Проверено','Checked')],x.records.map(p=>{const r=depositRoute(p.source);return `<tr><td>${p.id}<small>${escape(r.network)}</small><small class="full-address">${escape(p.tx)}</small></td><td>${ownMoney(p.units,r.asset)}</td><td>${pl(...depositLabels[p.status])}</td><td>${p.checkedAt||'—'}</td></tr>`;})):`<p>${pl('Поступлений пока нет. Проверка ищет перевод на выбранный кошелёк и не отправляет деньги.','No receipts yet. Checking looks for a transfer to the selected wallet and does not send funds.')}</p>`}</section>`;}
function depositPage(){if(!depositAllowed())return heading(pl('Пополнение доступно только владельцам','Funding is available to owners only'));const x=depositState(),r=depositRoute(x.source),p=depositCurrent(),funds=ownFunds(r.id);return `<div class="actions">${fbtn('К собственным средствам','Back to own funds','view','data-view="own"')}</div><p>${pl('Внесите собственные средства извне на кошелёк Shadow. Это финансирование, не доход и не деньги пользователей.','Deposit own funds from outside into a Shadow wallet. This is funding, not revenue or user money.')}</p><div class="support-layout"><section class="panel"><h2>${pl('Реквизиты для пополнения','Funding details')}</h2>${supportSelect('deposit-source',pl('Кошелёк, актив и сеть','Wallet, asset and network'),ownRoutes.map(r=>[r.id,r.asset+' · '+r.network+' · '+r.id]),x.source)}<p>${pl('Адрес кошелька Shadow','Shadow wallet address')}</p><p class="full-address">${r.address}</p><button type="button" class="btn" data-deposit-copy>${pl('Скопировать учебный адрес','Copy synthetic address')}</button><p class="support-notice">${pl('Учебный адрес — не отправляйте сюда реальные деньги. В рабочем сервисе здесь будут проверенные реквизиты.','Synthetic address — do not send real money here. The production service will show verified details.')}</p><p>${pl('Выберите у отправителя точно ту же сеть и актив. Комиссию отправитель оплачивает отдельно; учитывается фактически полученная сумма.','Choose exactly the same network and asset in the sending wallet. The sender pays its fee separately; only the actual amount received is recorded.')}</p><details><summary>${pl('Почему не нужно подтверждение второго владельца?','Why is no second owner approval needed?')}</summary><p>${pl('Здесь вы получаете реквизиты и проверяете входящий перевод. Админка не отправляет деньги и не позволяет вручную начислить баланс. Вывод по-прежнему подтверждают два владельца.','This screen provides deposit details and checks an incoming transfer. The admin does not send money or allow manual balance credits. Withdrawals still require two owners.')}</p></details></section><section class="panel"><h2>${pl('Поступление и баланс','Receipt and balance')}</h2><p class="badge ${p?.status==='confirmed'?'good':'warn'}">${pl(...depositLabels[p?.status||'waiting'])}</p><dl class="own-breakdown"><div><dt>${pl('Подтверждённый баланс','Confirmed balance')}</dt><dd>${ownMoney(funds.balance,r.asset)}</dd></div><div><dt>${pl('Зачислено в этом сеансе','Credited this session')}</dt><dd>${ownMoney(depositCredited(r.id),r.asset)}</dd></div><div><dt>${pl('Ожидает проверки','Awaiting verification')}</dt><dd>${ownMoney(x.records.filter(q=>q.source===r.id&&['pending','unknown'].includes(q.status)).reduce((n,q)=>n+q.units,0),r.asset)}</dd></div><div><dt>${pl('Доступно после резервов','Available after reserves')}</dt><dd>${ownMoney(funds.available,r.asset)}</dd></div></dl><button type="button" class="btn primary" data-deposit="check">${pl('Проверить поступление · демо','Check receipt · demo')}</button><p>${pl('Проверка не отправляет перевод. Зачисление происходит один раз после подтверждения сети и совпадения реквизитов.','Checking does not submit a transfer. Credit occurs once after network confirmation and matching details.')}</p>${p?.status==='confirmed'?`<button type="button" class="btn" data-deposit="withdraw">${pl('Открыть средства этого кошелька','Open this wallet’s funds')}</button>`:''}</section></div>${x.notice?`<p class="support-notice" role="status">${pl(...x.notice)}</p>`:''}${technicalLocked()?`<p role="status">${pl('Технический режим включён. Доступна только проверка поступления; она не снимает ограничения на расходование средств.','Technical mode is on. Receipt checking remains available; it does not lift spending restrictions.')}</p>`:''}${depositHistory()}<details class="panel"><summary>${pl('Учебные результаты проверки','Synthetic check results')}</summary>${supportSelect('deposit-outcome',pl('Ответ проверки','Check response'),Object.entries(depositLabels).filter(([k])=>!['waiting'].includes(k)).map(([k,v])=>[k,pl(...v)]),x.outcome)}<p>${pl('Пример: входящий перевод 250 единиц выбранного актива. Повторная проверка той же операции не увеличивает баланс второй раз. В прототипе нет подключения к сети.','Example: incoming transfer of 250 units of the selected asset. Rechecking the same transfer never credits it twice. The prototype is not connected to a network.')}</p></details>`;}
document.addEventListener('click',async e=>{const copy=e.target.closest('[data-deposit-copy]');if(copy&&depositAllowed()){const source=depositState().source;try{await navigator.clipboard.writeText(depositRoute(source).address);if(depositAllowed()&&depositState().source===source)depositState().notice=['Учебный адрес скопирован. Не отправляйте реальные деньги.','Synthetic address copied. Do not send real funds.'];}catch{if(depositAllowed())depositState().notice=['Не удалось скопировать. Выделите полный адрес выше.','Could not copy. Select the complete address above.'];}render();return;}const n=e.target.closest('[data-deposit]');if(n){depositAction(n.dataset.deposit);render();}});
document.addEventListener('change',e=>{if(!depositAllowed())return;if(e.target.id==='deposit-source'&&depositRoute(e.target.value)){depositState().source=e.target.value;depositState().notice=null;render();}if(e.target.id==='deposit-outcome'&&depositLabels[e.target.value])depositState().outcome=e.target.value;});
